(()=>{const toggle=document.getElementById('readerMenuToggle'),menu=document.getElementById('readerMenu');function close(){menu.hidden=true;toggle.setAttribute('aria-expanded','false')}toggle.onclick=()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)window.scrollTo({top:0,behavior:'instant'})};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){close();toggle.focus()}});})();
